/*
 * prog17_whitespace_trim
 *
 * Re‑implementation of the original program's observable behavior.
 * The original binary trims leading and trailing whitespace from its
 * first argument, collapses any internal runs of whitespace to a single
 * space, and prints the result.  If no argument is supplied, or the
 * resulting string is empty, it prints the literal word "EMPTY".
 *
 * The original binary also caps the processed input length at 400
 * characters – any characters beyond that are ignored.
 */

#include <stdio.h>
#include <string.h>
#include <ctype.h>

#define MAX_INPUT 400   /* limit imposed by the original binary */

int main(int argc, char *argv[])
{
    /* No argument supplied → print EMPTY */
    if (argc < 2) {
        puts("EMPTY");
        return 0;
    }

    const char *in = argv[1];
    size_t in_len = strlen(in);
    if (in_len > MAX_INPUT) {
        in_len = MAX_INPUT;          /* cap to 400 characters */
    }

    char out[MAX_INPUT + 1];         /* output buffer (max same size) */
    size_t out_len = 0;

    int seen_non_ws = 0;   /* have we output any non‑whitespace yet? */
    int prev_ws = 0;       /* was the previous processed character whitespace? */

    for (size_t i = 0; i < in_len; ++i) {
        unsigned char ch = (unsigned char)in[i];

        if (isspace(ch)) {
            /* Remember that we have seen whitespace only if we already
               started outputting non‑whitespace characters. */
            if (seen_non_ws) {
                prev_ws = 1;
            }
            continue;   /* skip all whitespace */
        }

        /* Non‑whitespace character */
        if (seen_non_ws && prev_ws) {
            /* Collapse a run of whitespace to a single space */
            out[out_len++] = ' ';
        }

        out[out_len++] = (char)ch;
        seen_non_ws = 1;
        prev_ws = 0;
    }

    out[out_len] = '\0';

    if (out_len == 0) {
        puts("EMPTY");
    } else {
        puts(out);
    }

    return 0;
}
